using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        // EF Core 9 Cosmos provider throws on sync I/O by default.
        // Re-enable sync calls for backward compatibility during migration.
        optionsBuilder.ConfigureWarnings(w =>
            w.Ignore(Microsoft.EntityFrameworkCore.Diagnostics.CosmosEventId.SyncNotSupported));
    }
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 renames the discriminator from "Discriminator" to "$type".
        // Preserve "Discriminator" so existing 500K documents remain readable
        // and direct SQL queries (WHERE c.Discriminator = ...) keep working.
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");
            entity.HasDiscriminator<string>("Discriminator");

            // EF Core 9 changes the default id format from "EntityType|Key" to just "Key".
            // Preserve the "Product|{Id}" format so existing documents are still found.
            entity.HasPartitionKey(p => p.Id);
            entity.Property(p => p.Id).ToJsonProperty("id")
                .HasValueGenerator<ProductIdValueGenerator>();
        });
    }
}

// Generates ids in the legacy "Product|{key}" format used by EF Core 8
class ProductIdValueGenerator : Microsoft.EntityFrameworkCore.ValueGeneration.ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;
    public override string Next(Microsoft.EntityFrameworkCore.ChangeTracking.EntityEntry entry)
    {
        var id = entry.Property("Id").CurrentValue;
        return $"Product|{id}";
    }
}

class Product { public int Id { get; set; } public string Sku { get; set; } }

