class CosmosQuery
{
    async Task FindProducts(ProductContext ctx)
    {
        // Direct Cosmos SQL — still works because we preserved the "Discriminator"
        // property name in OnModelCreating (EF Core 9 would default to "$type").
        var sql = "SELECT * FROM c WHERE c.Discriminator = 'Product' AND c.Sku = @sku";

        // EF Core 9 Cosmos provider no longer supports sync I/O by default.
        // Prefer async; sync is allowed only because we suppressed SyncNotSupported above.
        var products = await ctx.Products.Where(p => p.Sku == "ABC").ToListAsync();
    }
}

